/* Generated by port_site.py from the approved mockup. Behaviour for the control section; timers, listeners and observers go through ctx. */
export function init(ctx) {
  var reduce = ctx.reduce,
    root = document.documentElement;

  /* section 4: the visitor picks a mode; the handle glides to it and the sentence slides out and in, word by word (Motion) */
  (function () {
    var M = ctx.Motion,
      EASE = [0.22, 1, 0.36, 1],
      say = document.getElementById("say"),
      ghost = document.getElementById("ghost"),
      note = document.getElementById("s4note"),
      track = document.getElementById("track4"),
      knob = document.getElementById("knob"),
      pips = [].slice.call(track.querySelectorAll(".pip")),
      btns = [].slice.call(document.querySelectorAll(".stops4 button")),
      cur = -1,
      busy = false;
    var MODES = [
      {
        name: "Assist",
        a: "HAIP drafts.",
        b: "You send.",
        n: "Every reply waits for one tap from your team.",
      },
      {
        name: "Balanced",
        a: "HAIP answers.",
        b: "You quote.",
        n: "Rooms, dates and photos go out on their own. Prices come to you.",
      },
      {
        name: "Autopilot",
        a: "HAIP runs it.",
        b: "You step in.",
        n: "HAIP handles the whole chat and calls you in when it should.",
      },
    ];
    function line(t) {
      return (
        '<span class="ln">' +
        t
          .split(" ")
          .map(function (w) {
            return '<span class="w">' + w + "</span>";
          })
          .join("") +
        "</span>"
      );
    }
    function size() {
      track.style.setProperty("--tw", track.clientWidth - 28 + "px");
    }
    function paint(m, anim) {
      say.innerHTML = line(m.a) + line(m.b);
      note.textContent = m.n;
      if (anim && M && !reduce) {
        M.animate(
          say.querySelectorAll(".w"),
          {
            opacity: [0, 1],
            filter: ["blur(6px)", "blur(0px)"],
            transform: ["translateY(60%)", "translateY(0)"],
          },
          { delay: M.stagger(0.06), duration: 0.55, easing: EASE },
        );
        M.animate(
          note,
          { opacity: [0, 1], transform: ["translateY(6px)", "translateY(0)"] },
          { duration: 0.4, delay: 0.15, easing: EASE },
        );
        M.animate(
          ghost,
          {
            opacity: [0, 1],
            transform: ["translate(-46%,-50%)", "translate(-50%,-50%)"],
          },
          { duration: 0.6, easing: EASE },
        );
      }
      ghost.textContent = m.name;
    }
    function set(i, anim) {
      i = Math.max(0, Math.min(2, i));
      if (i === cur) return;
      var first = cur < 0;
      cur = i;
      var m = MODES[i];
      track.style.setProperty("--p", i / 2);
      knob.setAttribute("aria-valuenow", i);
      knob.setAttribute("aria-valuetext", m.name);
      pips.forEach(function (p, j) {
        p.classList.toggle("on", j <= i);
      });
      btns.forEach(function (b) {
        b.setAttribute("aria-pressed", String(Number(b.dataset.v) === i));
      });
      if (first || !anim || !M || reduce) {
        paint(m, false);
        return;
      }
      M.animate(
        say.querySelectorAll(".w"),
        {
          opacity: [1, 0],
          filter: ["blur(0px)", "blur(6px)"],
          transform: ["translateY(0)", "translateY(-60%)"],
        },
        { delay: M.stagger(0.03), duration: 0.25, easing: "ease-in" },
      );
      M.animate(note, { opacity: [1, 0] }, { duration: 0.2 });
      ctx.setTimeout(function () {
        paint(MODES[cur], true);
      }, 300);
    }
    var auto = null,
      seen = false,
      touched = false;
    function used() {
      knob.classList.add("used");
      touched = true;
      ctx.clearTimeout(auto);
    }
    function roll() {
      ctx.clearTimeout(auto);
      if (touched || reduce || document.hidden || !seen) return;
      auto = ctx.setTimeout(function () {
        set((cur + 1) % 3, true);
        roll();
      }, 2600);
    }
    btns.forEach(function (b) {
      ctx.on(b, "click", function () {
        used();
        set(Number(b.dataset.v), true);
      });
    });
    ctx.on(knob, "keydown", function (e) {
      var d =
        e.key === "ArrowRight" || e.key === "ArrowUp"
          ? 1
          : e.key === "ArrowLeft" || e.key === "ArrowDown"
            ? -1
            : 0;
      if (d) {
        e.preventDefault();
        used();
        set(cur + d, true);
      }
    });
    // drag: the handle follows the finger, then settles on the nearest stop
    function frac(x) {
      var r = track.getBoundingClientRect();
      return Math.max(0, Math.min(1, (x - r.left - 14) / (r.width - 28)));
    }
    ctx.on(track, "pointerdown", function (e) {
      used();
      knob.classList.add("drag");
      track.setPointerCapture(e.pointerId);
      track.style.setProperty("--p", frac(e.clientX));
      function mv(ev) {
        track.style.setProperty("--p", frac(ev.clientX));
      }
      function up(ev) {
        track.removeEventListener("pointermove", mv);
        track.removeEventListener("pointerup", up);
        track.removeEventListener("pointercancel", up);
        knob.classList.remove("drag");
        var i = Math.round(frac(ev.clientX) * 2);
        if (i === cur) track.style.setProperty("--p", cur / 2);
        else set(i, true);
      }
      ctx.on(track, "pointermove", mv);
      ctx.on(track, "pointerup", up);
      ctx.on(track, "pointercancel", up);
    });
    ctx.on(window, "resize", size);
    size();
    set(0, false);
    if ("IntersectionObserver" in window)
      ctx
        .io(
          function (es) {
            seen = es[0].isIntersecting;
            if (seen) roll();
            else ctx.clearTimeout(auto);
          },
          { threshold: 0.5 },
        )
        .observe(say);
    ctx.on(document, "visibilitychange", roll);
  })();
}
